    public void readFromNbt(NbtCompound tag) {
        tag.getList("records", NbtElement.COMPOUND_TYPE).stream()
            .mapMulti(MoreStreams.instanceOf(NbtCompound.class))
            .forEach(nbt -> DataResults.ifPresentOrElse(
